{"abstain":false,"explanation":"A generic parser for test-suite scope, named missing-command/module blockers, and explicitly installed remediation entities.","source":"def scope(current_command, parsed_clauses):
    clauses = parsed_clauses.get("clauses", []) if isinstance(parsed_clauses, dict) else []
    for clause in clauses:
        if clause.get("in_pipe") or clause.get("in_subst") or clause.get("in_loop"):
            continue
        argv = clause.get("argv") or []
        if not argv:
            continue
        candidate = argv[0].rsplit("/", 1)[-1]
        if len(argv) > 2 and argv[1] == "-m":
            candidate = argv[2]
        if re.fullmatch(r"[a-z0-9_.+-]*test[a-z0-9_.+-]*", candidate, re.I):
            return "test-suite"
    return None


def blocker_spans(result_excerpt):
    spans = []
    patterns = (
        r"(?i)\bno module named\s+[\"']?([A-Za-z][A-Za-z0-9_.-]*)[\"']?",
        r"(?im)(?:^|\n)[^\n]*?\b([A-Za-z][A-Za-z0-9_.+-]*):\s*(?:command\s+)?not found\b",
        r"(?im)\bcommand not found:\s*([A-Za-z][A-Za-z0-9_.+-]*)\b",
    )
    for pattern in patterns:
        for match in re.finditer(pattern, result_excerpt):
            span = [match.start(1), match.end(1)]
            if span not in spans:
                spans.append(span)
    spans.sort(key=lambda span: (span[0], span[1]))
    return spans


def remediation_spans(command):
    spans = []
    for marker in re.finditer(r"(?<![A-Za-z0-9_.-])install\b", command, re.I):
        end_match = re.search(r"(?:&&|\|\||[;|\n])", command[marker.end():])
        end = marker.end() + end_match.start() if end_match else len(command)
        segment = command[marker.end():end]
        for token in re.finditer(r"\"([^\"]*)\"|'([^']*)'|([^\s]+)", segment):
            group = 1 if token.group(1) is not None else 2 if token.group(2) is not None else 3
            value = token.group(group)
            if not value or value.startswith("-") or "/" in value or value.startswith("."):
                continue
            entity = re.match(r"[A-Za-z0-9][A-Za-z0-9_.-]*", value)
            if entity:
                start = marker.end() + token.start(group) + entity.start()
                span = [start, start + len(entity.group(0))]
                if span not in spans:
                    spans.append(span)
    spans.sort(key=lambda span: (span[0], span[1]))
    return spans"}
